use anyhow::Context;
use serde::ser::{Serialize, SerializeStruct, Serializer};

impl Serialize for Record {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use crate::usp_decoder::try_decode_msg;
        use record::RecordType::{
            Disconnect, MqttConnect, NoSessionContext, SessionContext, StompConnect,
            WebsocketConnect,
        };

        let mut state = serializer.serialize_struct("Record", 7)?;
        state.serialize_field("version", &self.version)?;
        state.serialize_field("to_id", &self.to_id)?;
        state.serialize_field("from_id", &self.from_id)?;
        state.serialize_field("originator_id", &self.originator_id)?;
        state.serialize_field("destination_id", &self.destination_id)?;
        state.serialize_field("payload_security", &self.payload_security)?;
        state.serialize_field("mac_signature", &self.mac_signature)?;
        state.serialize_field("sender_cert", &self.sender_cert)?;

        match &self.record_type {
            Some(NoSessionContext(context)) => {
                let msg = try_decode_msg(&context.payload);
                if let Ok(msg) = msg {
                    state.serialize_field("payload", &msg)?;
                } else {
                    Err(serde::ser::Error::custom(format!(
                        "{:?}",
                        msg.context("Interpreting USP Record payload as USP Msg")
                            .unwrap_err()
                    )))?;
                }
            }
            Some(SessionContext(context)) => {
                state.serialize_field("session_context", context)?;
            }
            Some(WebsocketConnect(ws)) => state.serialize_field("websocket_connect", ws)?,
            Some(MqttConnect(mqtt)) => state.serialize_field("mqtt_connect", mqtt)?,
            Some(StompConnect(stomp)) => state.serialize_field("stomp_connect", stomp)?,
            Some(Disconnect(disc)) => state.serialize_field("disconnect", disc)?,
            _ => Err(serde::ser::Error::custom(
                "Unknown/Unsupported record type!",
            ))?,
        }

        state.end()
    }
}

impl Serialize for PayloadSecurity {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use PayloadSecurity::{Plaintext, Tls12};
        match *self {
            Plaintext => serializer.serialize_unit_variant("PayloadSecurity", 0, "PLAINTEXT"),
            Tls12 => serializer.serialize_unit_variant("PayloadSecurity", 1, "TLS12"),
        }
    }
}

