impl Serialize for MqttVersion {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use MqttVersion::{V311, V5};

        let (value, index) = match self {
            V311 => ("V3_1_1", 0),
            V5 => ("V5", 1),
        };
        serializer.serialize_unit_variant("MQTTVersion", index, value)
    }
}

