impl Serialize for Header {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut state = serializer.serialize_struct("Header", 2)?;
        state.serialize_field("msg_id", &self.msg_id)?;
        if let Ok(typ) = MsgType::try_from(self.msg_type) {
            state.serialize_field("msg_type", &typ)?
        } else {
            state.serialize_field("msg_type", &self.msg_type)?;
        }
        state.end()
    }
}

impl Serialize for MsgType {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use MsgType::{
            Add, AddResp, Delete, DeleteResp, Deregister, DeregisterResp, Error, Get, GetInstances,
            GetInstancesResp, GetResp, GetSupportedDm, GetSupportedDmResp, GetSupportedProto,
            GetSupportedProtoResp, Notify, NotifyResp, Operate, OperateResp, Register,
            RegisterResp, Set, SetResp,
        };

        match *self {
            Error => serializer.serialize_unit_variant("MsgType", *self as u32, "ERROR"),
            Get => serializer.serialize_unit_variant("MsgType", *self as u32, "GET"),
            GetResp => serializer.serialize_unit_variant("MsgType", *self as u32, "GET_RESP"),
            Notify => serializer.serialize_unit_variant("MsgType", *self as u32, "NOTIFY"),
            Set => serializer.serialize_unit_variant("MsgType", *self as u32, "SET"),
            SetResp => serializer.serialize_unit_variant("MsgType", *self as u32, "SET_RESP"),
            Operate => serializer.serialize_unit_variant("MsgType", *self as u32, "OPERATE"),
            OperateResp => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "OPERATE_RESP")
            }
            Add => serializer.serialize_unit_variant("MsgType", *self as u32, "ADD"),
            AddResp => serializer.serialize_unit_variant("MsgType", *self as u32, "ADD_RESP"),
            Delete => serializer.serialize_unit_variant("MsgType", *self as u32, "DELETE"),
            DeleteResp => serializer.serialize_unit_variant("MsgType", *self as u32, "DELETE_RESP"),
            GetSupportedDm => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "GET_SUPPORTED_DM")
            }
            GetSupportedDmResp => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "GET_SUPPORTED_DM_RESP")
            }
            GetInstances => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "GET_INSTANCES")
            }
            GetInstancesResp => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "GET_INSTANCES_RESP")
            }
            NotifyResp => serializer.serialize_unit_variant("MsgType", *self as u32, "NOTIFY_RESP"),
            GetSupportedProto => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "GET_SUPPORTED_PROTO")
            }
            GetSupportedProtoResp => serializer.serialize_unit_variant(
                "MsgType",
                *self as u32,
                "GET_SUPPORTED_PROTO_RESP",
            ),
            Register => serializer.serialize_unit_variant("MsgType", *self as u32, "REGISTER"),
            RegisterResp => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "REGISTER_RESP")
            }
            Deregister => serializer.serialize_unit_variant("MsgType", *self as u32, "DEREGISTER"),
            DeregisterResp => {
                serializer.serialize_unit_variant("MsgType", *self as u32, "DEREGISTER_RESP")
            }
        }
    }
}

impl Serialize for Body {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use body::MsgBody;
        let mut state = serializer.serialize_struct("Body", 1)?;
        match &self.msg_body {
            Some(MsgBody::Request(ref m)) => state.serialize_field("Request", m)?,
            Some(MsgBody::Response(ref m)) => state.serialize_field("Response", m)?,
            Some(MsgBody::Error(ref m)) => state.serialize_field("Error", m)?,
            None => Err(serde::ser::Error::custom("USP Msg without body?!?"))?,
        }
        state.end()
    }
}

impl Serialize for Request {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use request::ReqType;
        let mut state = serializer.serialize_struct("Request", 1)?;
        match &self.req_type {
            Some(ReqType::Get(ref m)) => state.serialize_field("Get", &m)?,
            Some(ReqType::GetSupportedDm(ref m)) => state.serialize_field("GetSupportedDM", &m)?,
            Some(ReqType::GetInstances(ref m)) => state.serialize_field("GetInstances", &m)?,
            Some(ReqType::Set(ref m)) => state.serialize_field("Set", &m)?,
            Some(ReqType::Add(ref m)) => state.serialize_field("Add", &m)?,
            Some(ReqType::Delete(ref m)) => state.serialize_field("Delete", &m)?,
            Some(ReqType::Operate(ref m)) => state.serialize_field("Operate", &m)?,
            Some(ReqType::Notify(ref m)) => state.serialize_field("Notify", &m)?,
            Some(ReqType::GetSupportedProtocol(ref m)) => {
                state.serialize_field("GetSupportedProtocol", &m)?
            }
            Some(ReqType::Register(ref m)) => state.serialize_field("Register", &m)?,
            Some(ReqType::Deregister(ref m)) => state.serialize_field("Deregister", &m)?,
            None => Err(serde::ser::Error::custom("USP Request Msg without type?!?"))?,
        }
        state.end()
    }
}

impl Serialize for Response {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use response::RespType;
        let mut state = serializer.serialize_struct("Response", 1)?;
        match &self.resp_type {
            Some(RespType::GetResp(ref m)) => state.serialize_field("GetResp", &m)?,
            Some(RespType::GetSupportedDmResp(ref m)) => {
                state.serialize_field("GetSupportedDMResp", &m)?
            }
            Some(RespType::GetInstancesResp(ref m)) => {
                state.serialize_field("GetInstancesResp", &m)?
            }
            Some(RespType::SetResp(ref m)) => state.serialize_field("SetResp", &m)?,
            Some(RespType::AddResp(ref m)) => state.serialize_field("AddResp", &m)?,
            Some(RespType::DeleteResp(ref m)) => state.serialize_field("DeleteResp", &m)?,
            Some(RespType::OperateResp(ref m)) => state.serialize_field("OperateResp", &m)?,
            Some(RespType::NotifyResp(ref m)) => state.serialize_field("NotifyResp", &m)?,
            Some(RespType::GetSupportedProtocolResp(ref m)) => {
                state.serialize_field("GetSupportedProtocolResp", &m)?;
            }
            Some(RespType::RegisterResp(ref m)) => state.serialize_field("RegisterResp", &m)?,
            Some(RespType::DeregisterResp(ref m)) => state.serialize_field("DeregisterResp", &m)?,
            None => Err(serde::ser::Error::custom(
                "USP Response Msg without type?!?",
            ))?,
        }
        state.end()
    }
}

