impl Serialize for Notify {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        use notify::Notification;
        let mut state = serializer.serialize_struct("Notify", 3)?;
        state.serialize_field("subscription_id", &self.subscription_id)?;
        state.serialize_field("send_resp", &self.send_resp)?;

        match &self.notification {
            Some(Notification::Event(ref m)) => state.serialize_field("event", &m)?,
            Some(Notification::ValueChange(ref m)) => state.serialize_field("value_change", &m)?,
            Some(Notification::ObjCreation(ref m)) => state.serialize_field("obj_creation", &m)?,
            Some(Notification::ObjDeletion(ref m)) => state.serialize_field("obj_deletion", &m)?,
            Some(Notification::OperComplete(ref m)) => {
                state.serialize_field("oper_complete", &m)?
            }
            Some(Notification::OnBoardReq(ref m)) => state.serialize_field("on_board_req", &m)?,
            None => Err(serde::ser::Error::custom("Unknown USP Notify type"))?,
        }

        state.end()
    }
}

